  case 'suggestions':
   $q=trim((string)($_GET['q']??'')); if($q==='') ok([]); if(strlen($q)>80)$q=substr($q,0,80); $term='%'.$q.'%';
   $s=db()->prepare("SELECT p.id,p.name,p.brand,c.name category,p.image,p.price original_price,CASE WHEN d.id IS NOT NULL THEN CASE WHEN d.discount_type='percentage' THEN ROUND(p.price*(1-d.discount_value/100),2) ELSE GREATEST(0,p.price-d.discount_value) END ELSE p.price END deal_price,d.id deal_id FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN deals d ON d.product_id=p.id AND d.is_active=1 AND d.start_at<=NOW() AND d.end_at>NOW() WHERE p.active=1 AND (p.name LIKE ? OR p.brand LIKE ? OR c.name LIKE ? OR p.description LIKE ?) ORDER BY CASE WHEN LOWER(p.name)=LOWER(?) THEN 0 WHEN LOWER(p.name) LIKE LOWER(?) THEN 1 WHEN LOWER(p.brand) LIKE LOWER(?) THEN 2 ELSE 3 END,p.featured DESC,p.id DESC LIMIT 8");$s->execute([$term,$term,$term,$term,$q,$q.'%',$q.'%']);ok($s->fetchAll());
