   $s=db()->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"customer")'); try{$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);}catch(PDOException $e){if($e->errorInfo[1]===1062)fail('Email already registered',409);throw $e;}
   $_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer']; ok($_SESSION['user']);
