  case 'products':
   $sql="SELECT p.*,c.name category,p.price original_price,CASE WHEN d.id IS NOT NULL THEN CASE WHEN d.discount_type='percentage' THEN ROUND(p.price*(1-d.discount_value/100),2) ELSE GREATEST(0,p.price-d.discount_value) END ELSE p.price END deal_price,d.id deal_id,d.discount_type,d.discount_value,d.start_at,d.end_at FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN deals d ON d.product_id=p.id AND d.is_active=1 AND d.start_at<=NOW() AND d.end_at>NOW() WHERE p.active=1";$args=[];
   if(!empty($_GET['q'])){$sql.=' AND (p.name LIKE ? OR p.brand LIKE ? OR p.description LIKE ? OR c.name LIKE ?)';$q='%'.$_GET['q'].'%';$args=[$q,$q,$q,$q];} if(!empty($_GET['category'])){$sql.=' AND c.name=?';$args[]=$_GET['category'];}if(!empty($_GET['deals']))$sql.=' AND d.id IS NOT NULL';$sql.=' ORDER BY p.featured DESC,p.id DESC';$s=db()->prepare($sql);$s->execute($args);ok($s->fetchAll());
  case 'product': $s=db()->prepare("SELECT p.*,c.name category,p.price original_price,CASE WHEN d.id IS NOT NULL THEN CASE WHEN d.discount_type='percentage' THEN ROUND(p.price*(1-d.discount_value/100),2) ELSE GREATEST(0,p.price-d.discount_value) END ELSE p.price END deal_price,d.id deal_id,d.discount_type,d.discount_value,d.start_at,d.end_at FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN deals d ON d.product_id=p.id AND d.is_active=1 AND d.start_at<=NOW() AND d.end_at>NOW() WHERE p.id=? AND p.active=1");$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch();if(!$p)fail('Product not found',404);ok($p);
  case 'cart': $u=require_login();$s=db()->prepare("SELECT ci.product_id id,ci.quantity qty,p.name,p.price original_price,CASE WHEN d.id IS NOT NULL THEN CASE WHEN d.discount_type='percentage' THEN ROUND(p.price*(1-d.discount_value/100),2) ELSE GREATEST(0,p.price-d.discount_value) END ELSE p.price END price,p.stock,p.image FROM cart_items ci JOIN products p ON p.id=ci.product_id LEFT JOIN deals d ON d.product_id=p.id AND d.is_active=1 AND d.start_at<=NOW() AND d.end_at>NOW() WHERE ci.user_id=?");$s->execute([$u['id']]);ok($s->fetchAll());
  case 'cart_add': case 'cart_update': case 'cart_remove':
   require_csrf();$u=require_login();$id=(int)($body['product_id']??0);$qty=$action==='cart_remove'?0:max(0,(int)($body['quantity']??1));$p=db()->prepare('SELECT id,stock FROM products WHERE id=? AND active=1');$p->execute([$id]);$product=$p->fetch();if(!$product)fail('Invalid product',404);if($qty>$product['stock'])fail('Insufficient stock',409);
   if($qty===0)$s=db()->prepare('DELETE FROM cart_items WHERE user_id=? AND product_id=?');else $s=db()->prepare('INSERT INTO cart_items(user_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=VALUES(quantity)');$s->execute($qty===0?[$u['id'],$id]:[$u['id'],$id,$qty]);ok();
  case 'checkout':
   require_csrf();$u=require_login();$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("SELECT ci.product_id,ci.quantity,p.name,p.stock,CASE WHEN d.id IS NOT NULL THEN CASE WHEN d.discount_type='percentage' THEN ROUND(p.price*(1-d.discount_value/100),2) ELSE GREATEST(0,p.price-d.discount_value) END ELSE p.price END final_price FROM cart_items ci JOIN products p ON p.id=ci.product_id LEFT JOIN deals d ON d.product_id=p.id AND d.is_active=1 AND d.start_at<=NOW() AND d.end_at>NOW() WHERE ci.user_id=? FOR UPDATE");$s->execute([$u['id']]);$items=$s->fetchAll();if(!$items){$pdo->rollBack();fail('Cart is empty');}$total=0;foreach($items as $i){if($i['quantity']>$i['stock']){$pdo->rollBack();fail('Insufficient stock for '.$i['name'],409);}$total+=(float)$i['final_price']*$i['quantity'];}$s=$pdo->prepare('INSERT INTO orders(user_id,total,status,payment_method,shipping_name,shipping_email,shipping_address) VALUES(?,?,"Pending","Cash on Delivery",?,?,?)');$s->execute([$u['id'],$total,$body['name']??$u['name'],$body['email']??$u['email'],$body['address']??'']);$oid=(int)$pdo->lastInsertId();$oi=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity) VALUES(?,?,?,?,?)');$up=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($items as $i){$oi->execute([$oid,$i['product_id'],$i['name'],$i['final_price'],$i['quantity']]);$up->execute([$i['quantity'],$i['product_id']]);}$pdo->prepare('DELETE FROM cart_items WHERE user_id=?')->execute([$u['id']]);$pdo->commit();ok(['order_id'=>$oid,'total'=>$total]);
  case 'orders': $u=require_login();$s=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();$items=db()->prepare('SELECT oi.*,p.image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');foreach($rows as &$row){$items->execute([$row['id']]);$row['items']=$items->fetchAll();}$items=null;unset($row);ok($rows);
  case 'admin_products': require_admin();if($method==='GET'){ok(db()->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll());}require_csrf();$id=(int)($body['id']??0);$cat=(int)($body['category_id']??0);if(!$cat&&!empty($body['category'])){$c=db()->prepare('SELECT id FROM categories WHERE name=?');$c->execute([$body['category']]);$cat=(int)$c->fetchColumn();}if($id){$s=db()->prepare('UPDATE products SET name=?,category_id=?,price=?,stock=?,image=?,description=? WHERE id=?');$s->execute([$body['name'],$cat,$body['price'],$body['stock'],$body['image']??'laptop.svg',$body['description']??'',$id]);}else{$s=db()->prepare('INSERT INTO products(name,category_id,price,stock,image,description) VALUES(?,?,?,?,?,?)');$s->execute([$body['name'],$cat,$body['price'],$body['stock'],$body['image']??'laptop.svg',$body['description']??'']);}ok();
  case 'admin_product_delete': require_admin();require_csrf();$s=db()->prepare('UPDATE products SET active=0 WHERE id=?');$s->execute([(int)($body['id']??0)]);ok();
  case 'deals': $s=db()->prepare("SELECT d.*,p.name,p.brand,p.image,p.price original_price,c.name category,CASE WHEN d.discount_type='percentage' THEN ROUND(p.price*(1-d.discount_value/100),2) ELSE GREATEST(0,p.price-d.discount_value) END deal_price FROM deals d JOIN products p ON p.id=d.product_id JOIN categories c ON c.id=p.category_id WHERE d.is_active=1 AND d.start_at<=NOW() AND d.end_at>NOW() ORDER BY d.end_at ASC");$s->execute();ok($s->fetchAll());
  case 'admin_deals': require_admin();if($method==='GET'){ok(db()->query("SELECT d.*,p.name,p.brand,p.price original_price,CASE WHEN d.discount_type='percentage' THEN ROUND(p.price*(1-d.discount_value/100),2) ELSE GREATEST(0,p.price-d.discount_value) END deal_price FROM deals d JOIN products p ON p.id=d.product_id ORDER BY d.end_at DESC")->fetchAll());}require_csrf();$id=(int)($body['id']??0);$product=(int)($body['product_id']??0);$type=($body['discount_type']??'percentage');$value=(float)($body['discount_value']??0);$start=str_replace('T',' ',trim((string)($body['start_at']??'')));$end=str_replace('T',' ',trim((string)($body['end_at']??'')));if(!in_array($type,['percentage','fixed'],true)||$value<=0||$start===''||$end===''||strtotime($end)<=strtotime($start))fail('Invalid deal values');$q=db()->prepare('SELECT price FROM products WHERE id=? AND active=1');$q->execute([$product]);$base=(float)$q->fetchColumn();if(!$base)fail('Product not found',404);if(($type==='percentage'&&$value>100)||($type==='fixed'&&$value>=$base))fail('Discount cannot exceed product price');if($id){$s=db()->prepare('UPDATE deals SET product_id=?,discount_type=?,discount_value=?,start_at=?,end_at=?,is_active=? WHERE id=?');$s->execute([$product,$type,$value,$start,$end,(int)($body['is_active']??1),$id]);}else{$s=db()->prepare('INSERT INTO deals(product_id,discount_type,discount_value,start_at,end_at,is_active) VALUES(?,?,?,?,?,?)');$s->execute([$product,$type,$value,$start,$end,(int)($body['is_active']??1)]);}ok();
  case 'admin_deal_delete': require_admin();require_csrf();$s=db()->prepare('DELETE FROM deals WHERE id=?');$s->execute([(int)($body['id']??0)]);ok();
  case 'admin_orders': require_admin();if($method==='GET'){$rows=db()->query('SELECT o.*,u.name customer_name,u.email customer_email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll();$items=db()->prepare('SELECT oi.*,p.image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');foreach($rows as &$row){$items->execute([$row['id']]);$row['items']=$items->fetchAll();}$items=null;unset($row);ok($rows);}require_csrf();$id=(int)($body['id']??0);$status=(string)($body['status']??'');$allowed=['Pending'=>['Confirmed','Cancelled'],'Confirmed'=>['Processing','Cancelled'],'Processing'=>['Shipped','Cancelled'],'Shipped'=>['Delivered'],'Delivered'=>[],'Cancelled'=>[]];if(!array_key_exists($status,$allowed))fail('Invalid order status');$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT status FROM orders WHERE id=? FOR UPDATE');$s->execute([$id]);$previous=$s->fetchColumn();if($previous===false){$pdo->rollBack();fail('Order not found',404);}if($previous!==$status&&!in_array($status,$allowed[$previous],true)){ $pdo->rollBack();fail('Invalid status transition from '.$previous,409);}if($previous!==$status){$u=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$u->execute([$status,$id]);$h=$pdo->prepare('INSERT INTO order_status_history(order_id,previous_status,new_status,changed_by) VALUES(?,?,?,?)');$h->execute([$id,$previous,$status,user()['id']]);}$pdo->commit();ok(['id'=>$id,'status'=>$status]);
  default: fail('Unknown API action',404);
 }
} catch(Throwable $e) { error_log($e->getMessage()); fail('Server error',500); }
